import json,re
e=json.load(open('.ai/task/repair-w31-20260925/CONTEXTUAL-ENVELOPE-f3a2.json'))
pat=re.compile(r'%[-0-9.]*[a-z%]|#[A-Z_]+#|<\?.*?\?>|\[/?i\]')
for i,t in enumerate(e['payload']['translation_snapshot']):
    s,g=t['source'],t['target']
    a=sorted(pat.findall(s));b=sorted(pat.findall(g))
    if a!=b: print(i+1,'PH',set(a)^set(b), len(a),len(b))
    if s.count('\n')!=g.count('\n'): print(i+1,'LF',s.count('\n'),g.count('\n'))
    ls=[re.match(r'\t*',l).group() for l in s.split('\n')]; lg=[re.match(r'\t*',l).group() for l in g.split('\n')]
    if ls!=lg: print(i+1,'TAB')
EOF
